window.__AI_AGENTS_LESSONS__ = window.__AI_AGENTS_LESSONS__ || {};
window.__AI_AGENTS_LESSONS__["16-deploying-scalable-agents"] = {"slug": "16-deploying-scalable-agents", "en": {"title": "Deploying Scalable Agents with Microsoft Foundry", "sections": [{"id": "ai-sec-1", "level": 2, "title": "Introduction"}, {"id": "ai-sec-2", "level": 2, "title": "Learning Goals"}, {"id": "ai-sec-3", "level": 2, "title": "Prerequisites"}, {"id": "ai-sec-4", "level": 2, "title": "From Prototype to Production: What Actually Changes"}, {"id": "ai-sec-5", "level": 2, "title": "Agent Deployment Patterns"}, {"id": "ai-sec-6", "level": 3, "title": "1. Client-Hosted Agents"}, {"id": "ai-sec-7", "level": 3, "title": "2. Hosted Agents (Foundry Agent Service)"}, {"id": "ai-sec-8", "level": 3, "title": "3. Agent Workflows"}, {"id": "ai-sec-9", "level": 2, "title": "The Agent Lifecycle on Microsoft Foundry"}, {"id": "ai-sec-10", "level": 2, "title": "Scaling Strategies"}, {"id": "ai-sec-11", "level": 2, "title": "Observability in Production"}, {"id": "ai-sec-12", "level": 2, "title": "Cost Optimisation"}, {"id": "ai-sec-13", "level": 2, "title": "Enterprise Deployment Considerations"}, {"id": "ai-sec-14", "level": 2, "title": "Hands-On Lab: A Production-Ready Customer Support Agent"}, {"id": "ai-sec-15", "level": 3, "title": "Walkthrough"}, {"id": "ai-sec-16", "level": 2, "title": "Validating a Deployed Agent with Smoke Tests"}, {"id": "ai-sec-17", "level": 2, "title": "Knowledge Check"}, {"id": "ai-sec-18", "level": 2, "title": "Assignment"}, {"id": "ai-sec-19", "level": 2, "title": "Summary"}, {"id": "ai-sec-20", "level": 2, "title": "Additional Resources"}, {"id": "ai-sec-21", "level": 2, "title": "Previous Lesson"}, {"id": "ai-sec-22", "level": 2, "title": "Next Lesson"}], "html": "<h1 id=\"ai-sec-1\" class=\"cs-h1\">Deploying Scalable Agents with Microsoft Foundry</h1>\n<blockquote class=\"cs-quote\">[Figure: Deploying Scalable Agents]</blockquote>\n<p>Up to this point in the course you have built agents that run on your laptop, inside a notebook, driven by <code>az login</code> and a handful of environment variables. That is exactly the right way to learn. It is not the right way to run an agent that thousands of customers depend on at 3 a.m.</p>\n<p>This lesson is about the gap between \"it works on my machine\" and \"it works, reliably and affordably, in production.\" We close that gap using <strong>Microsoft Foundry</strong> and the <strong>Microsoft Foundry Agent Service</strong>, and we do it by building a real customer support agent that has tools, retrieval, memory, evaluation, and monitoring.</p>\n<h2 id=\"ai-sec-1\" class=\"cs-h2\">Introduction</h2>\n<p>This lesson will cover:</p>\n<ul class=\"cs-list\">\n<li>The difference between a <strong>prototype agent</strong> and a <strong>deployed agent</strong>, and why the transition is mostly about everything <em>around</em> the model.</li>\n<li><strong>Deployment patterns</strong> for agents: client-hosted, service-hosted (Hosted Agents), and workflow-orchestrated.</li>\n<li>The <strong>agent lifecycle</strong> on Microsoft Foundry — create, version, deploy, evaluate, observe, retire.</li>\n<li><strong>Scaling strategies</strong>: model routing, caching, concurrency, and stateless design.</li>\n<li><strong>Observability</strong> with OpenTelemetry and Foundry tracing.</li>\n<li><strong>Cost optimisation</strong> through model selection, routing, and evaluation gates.</li>\n<li><strong>Enterprise considerations</strong>: governance, human approval, and running MCP servers safely in production.</li>\n</ul>\n<h2 id=\"ai-sec-2\" class=\"cs-h2\">Learning Goals</h2>\n<p>After completing this lesson, you will know how to:</p>\n<ul class=\"cs-list\">\n<li>Choose the right deployment pattern for a given agent workload.</li>\n<li>Deploy an agent to the Microsoft Foundry Agent Service so it is versioned, governed, and observable.</li>\n<li>Instrument an agent for tracing and wire up an evaluation pipeline that runs before every release.</li>\n<li>Apply model routing and caching to keep latency and cost under control at scale.</li>\n<li>Add a human approval gate for high-risk actions and integrate an MCP server in a production-safe way.</li>\n</ul>\n<h2 id=\"ai-sec-3\" class=\"cs-h2\">Prerequisites</h2>\n<p>This lesson assumes you have completed the earlier lessons and are comfortable with:</p>\n<ul class=\"cs-list\">\n<li>Building agents with the <strong>Microsoft Agent Framework</strong> (Lesson 14).</li>\n<li><strong>Tool Use</strong> (Lesson 4) and <strong>Agentic RAG</strong> (Lesson 5).</li>\n<li><strong>Agent Memory</strong> (Lesson 13) and <strong>Agentic Protocols / MCP</strong> (Lesson 11).</li>\n<li><strong>Observability and Evaluation</strong> (Lesson 10) — this lesson builds directly on it.</li>\n</ul>\n<p>You will also need:</p>\n<ul class=\"cs-list\">\n<li>An <strong>Azure subscription</strong> and a <strong>Microsoft Foundry project</strong> with at least one deployed chat model.</li>\n<li>The <strong>Azure CLI</strong> authenticated (<code>az login</code>).</li>\n<li>Python 3.12+ and the packages in the repository <strong><code>requirements.txt</code></strong>.</li>\n</ul>\n<h2 id=\"ai-sec-4\" class=\"cs-h2\">From Prototype to Production: What Actually Changes</h2>\n<p>A prototype agent and a production agent share the same core loop — reason, call tools, respond. What changes is everything wrapped around that loop. The model is maybe 20% of a production agent; the other 80% is the operational skeleton.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Concern</th><th>Prototype</th><th>Production</th></tr></thead><tbody>\n<tr><td><strong>Hosting</strong></td><td>Runs in your notebook</td><td>Runs as a hosted service, versioned and rolled out</td></tr>\n<tr><td><strong>Identity</strong></td><td>Your <code>az login</code> token</td><td>Managed identity with scoped RBAC</td></tr>\n<tr><td><strong>State</strong></td><td>In-memory, lost on restart</td><td>Externalised (thread store, memory service)</td></tr>\n<tr><td><strong>Failure</strong></td><td>You see the traceback</td><td>Retries, fallbacks, dead-letter, alerts</td></tr>\n<tr><td><strong>Cost</strong></td><td>\"It's a few cents\"</td><td>Tracked per request, routed, cached, budgeted</td></tr>\n<tr><td><strong>Quality</strong></td><td>You eyeball the output</td><td>Evaluated automatically before every release</td></tr>\n<tr><td><strong>Trust</strong></td><td>You approve every action</td><td>Policy + human-in-the-loop for risky actions</td></tr>\n</tbody></table></div>\n<p>Keep this table in mind. Every section below maps to one of these rows.</p>\n<h2 id=\"ai-sec-5\" class=\"cs-h2\">Agent Deployment Patterns</h2>\n<p>There are three patterns you will use, often in combination.</p>\n<h3 id=\"ai-sec-6\" class=\"cs-h3\">1. Client-Hosted Agents</h3>\n<p>The agent object lives inside <em>your</em> application process. Your code calls the model provider directly; the reasoning loop runs in your service. This is what every previous lesson has done.</p>\n<ul class=\"cs-list\">\n<li><strong>Use it when</strong> you need full control over the loop, custom middleware, or you are embedding the agent inside an existing backend.</li>\n<li><strong>Trade-off</strong>: you own scaling, state, and resilience yourself.</li>\n</ul>\n<h3 id=\"ai-sec-7\" class=\"cs-h3\">2. Hosted Agents (Foundry Agent Service)</h3>\n<p>The agent is <em>registered as a resource</em> in Microsoft Foundry. Foundry hosts the reasoning loop, stores threads, enforces content safety and RBAC, and makes the agent visible in the Foundry portal. Your app becomes a thin client that creates threads and reads responses.</p>\n<ul class=\"cs-list\">\n<li><strong>Use it when</strong> you want durability, built-in observability, governance, and less operational surface area.</li>\n<li><strong>Trade-off</strong>: less low-level control in exchange for a managed runtime.</li>\n</ul>\n<h3 id=\"ai-sec-8\" class=\"cs-h3\">3. Agent Workflows</h3>\n<p>Multiple agents (and tools) are composed into a graph with explicit control flow — sequential steps, branching, human approval nodes, and durable checkpoints that can pause and resume. This is the Microsoft Agent Framework <strong>Workflows</strong> capability applied at deployment scale.</p>\n<ul class=\"cs-list\">\n<li><strong>Use it when</strong> a single task spans several specialised agents or requires an approval step in the middle.</li>\n<li><strong>Trade-off</strong>: more moving parts; needs orchestration-level observability.</li>\n</ul>\n<pre class=\"cs-code\"><code>flowchart TB\n    subgraph P1[Client-Hosted]\n        A1[Your App Process] --&gt; M1[Model Provider]\n    end\n    subgraph P2[Hosted Agent]\n        A2[Thin Client] --&gt; F2[Foundry Agent Service]\n        F2 --&gt; M2[Model + Tools + Thread Store]\n    end\n    subgraph P3[Agent Workflow]\n        A3[Orchestrator] --&gt; S1[Triage Agent]\n        S1 --&gt; S2[Resolver Agent]\n        S2 --&gt; H[Human Approval Node]\n        H --&gt; S3[Action Agent]\n    end</code></pre>\n<h2 id=\"ai-sec-9\" class=\"cs-h2\">The Agent Lifecycle on Microsoft Foundry</h2>\n<p>Deploying an agent is not a one-time <code>push</code>. It is a loop, and it looks a lot like a software release cycle because that is exactly what it is.</p>\n<pre class=\"cs-code\"><code>flowchart LR\n    Create[Create / Author] --&gt; Version[Version]\n    Version --&gt; Evaluate[Evaluate offline]\n    Evaluate --&gt;|passes gate| Deploy[Deploy hosted]\n    Evaluate --&gt;|fails gate| Create\n    Deploy --&gt; Observe[Observe online]\n    Observe --&gt; Improve[Collect failures]\n    Improve --&gt; Create\n    Deploy --&gt; Retire[Retire old version]</code></pre>\n<p>The key idea, carried over from <strong>Lesson 10</strong>: <strong>offline evaluation is a gate, not an afterthought.</strong> A new agent version does not ship unless it clears your evaluation thresholds. Online observability then feeds real-world failures back into your offline test set. That is the whole loop.</p>\n<h2 id=\"ai-sec-10\" class=\"cs-h2\">Scaling Strategies</h2>\n<p>Scaling an agent is different from scaling a stateless web API, because each request can trigger multiple expensive model and tool calls. Four techniques carry most of the load.</p>\n<p><strong>Stateless request handling.</strong> Keep no per-user state in your process memory. Persist conversation threads in the Foundry thread store or a memory service so any instance can handle any request. This is what lets you scale horizontally — add instances, no sticky sessions.</p>\n<p><strong>Model routing.</strong> Not every request needs your most capable (and most expensive) model. Route simple requests — intent classification, short factual answers — to a small, fast model, and reserve the large model for genuine reasoning. Foundry's <strong>Model Router</strong> can do this for you, or you can implement a lightweight classifier yourself. You will build the DIY version in the lab.</p>\n<p><strong>Response caching.</strong> Many support queries are near-duplicates (\"how do I reset my password?\"). Cache answers to common questions and serve them without hitting the model at all. Even a modest cache hit rate meaningfully cuts cost and latency.</p>\n<p><strong>Concurrency and backpressure.</strong> Model providers have rate limits. Bound your concurrency, use retries with exponential backoff, and fail gracefully (a queued \"we're on it\" response beats a 500).</p>\n<pre class=\"cs-code\"><code>flowchart LR\n    Q[User query] --&gt; C{Cache hit?}\n    C --&gt;|yes| R[Return cached answer]\n    C --&gt;|no| Router{Complexity?}\n    Router --&gt;|simple| SLM[Small model]\n    Router --&gt;|complex| LLM[Large model]\n    SLM --&gt; Out[Response]\n    LLM --&gt; Out\n    Out --&gt; Store[Cache + trace]</code></pre>\n<h2 id=\"ai-sec-11\" class=\"cs-h2\">Observability in Production</h2>\n<p>You cannot operate what you cannot see. As covered in Lesson 10, the Microsoft Agent Framework emits <strong>OpenTelemetry</strong> traces natively — every model call, tool invocation, and orchestration step becomes a span. In production you export those spans to Microsoft Foundry (or any OTel-compatible backend) so you can:</p>\n<ul class=\"cs-list\">\n<li>Trace a single customer complaint end-to-end across every model and tool call.</li>\n<li>Watch p50/p95 latency and cost per request over time.</li>\n<li>Alert on error-rate spikes and cost anomalies before your users (or your finance team) notice.</li>\n</ul>\n<pre class=\"cs-code\"><code>from agent_framework.observability import get_tracer\n\ntracer = get_tracer()\n\nwith tracer.start_as_current_span(&quot;support_request&quot;) as span:\n    span.set_attribute(&quot;customer.tier&quot;, &quot;enterprise&quot;)\n    span.set_attribute(&quot;routed.model&quot;, &quot;gpt-5-nano&quot;)\n    # agent execution is traced automatically inside this span</code></pre>\n<p>Attributes like <code>customer.tier</code> and <code>routed.model</code> are what turn a wall of traces into answerable questions (\"are enterprise customers getting routed to the small model too often?\").</p>\n<h2 id=\"ai-sec-12\" class=\"cs-h2\">Cost Optimisation</h2>\n<p>Cost in production agents is dominated by tokens. Three levers, in order of impact:</p>\n<ol class=\"cs-list\">\n<li><strong>Right-size the model.</strong> A small model that passes your evaluation gate is almost always cheaper than a large one that also passes. Use evaluation to <em>prove</em> the small model is good enough rather than defaulting to the biggest model out of caution.</li>\n<li><strong>Route by complexity.</strong> As above — pay large-model prices only for requests that need large-model reasoning.</li>\n<li><strong>Cache aggressively.</strong> The cheapest model call is the one you never make.</li>\n</ol>\n<p>Evaluation gates and cost control are the same discipline viewed from two angles: evaluation tells you the <em>quality floor</em>, routing and caching keep you as close to that floor's <em>cost</em> as possible.</p>\n<h2 id=\"ai-sec-13\" class=\"cs-h2\">Enterprise Deployment Considerations</h2>\n<p><strong>Governance.</strong> Hosted Agents inherit Foundry's RBAC, content safety, and audit logging. Give each agent a managed identity with the least privilege it needs — read-only access to the knowledge base, scoped access to the ticketing API, nothing more.</p>\n<p><strong>Human-in-the-loop.</strong> Some actions are too consequential to automate outright — issuing a refund, deleting an account, escalating to a legal team. The Microsoft Agent Framework supports <strong>approval-required</strong> tools: the agent proposes the action, execution pauses, a human approves or rejects, and the workflow resumes. You saw the primitive in <strong>Lesson 6</strong>; here you deploy it.</p>\n<p><strong>MCP in production.</strong> <strong>MCP</strong> lets your agent consume external tools through a standard interface. In production, treat every MCP server as an untrusted boundary: pin the server version, run it with a scoped identity, validate its outputs, and never expose secrets to it. An MCP server is a dependency, and dependencies get patched, audited, and rate-limited.</p>\n<pre class=\"cs-code\"><code>flowchart TB\n    subgraph Dev[Development Architecture]\n        D1[Notebook] --&gt; D2[Agent Framework]\n        D2 --&gt; D3[Model Provider]\n        D2 --&gt; D4[Local tools]\n    end\n    subgraph Deploy[Deployment Architecture]\n        E1[CI pipeline] --&gt; E2[Evaluation gate]\n        E2 --&gt;|pass| E3[Foundry Agent Service]\n        E3 --&gt; E4[Versioned hosted agent]\n    end\n    subgraph Run[Runtime Architecture]\n        F1[Client app] --&gt; F2[Hosted agent]\n        F2 --&gt; F3[Model Router]\n        F2 --&gt; F4[Azure AI Search RAG]\n        F2 --&gt; F5[Memory service]\n        F2 --&gt; F6[MCP tools]\n        F2 --&gt; F7[OTel -&gt; Foundry tracing]\n        F2 --&gt; F8[Human approval]\n    end</code></pre>\n<p>Those three diagrams — development, deployment, runtime — are the same agent at three stages of its life. The lab that follows walks you through building it.</p>\n<h2 id=\"ai-sec-14\" class=\"cs-h2\">Hands-On Lab: A Production-Ready Customer Support Agent</h2>\n<p>Open <strong><code>code_samples/16-python-agent-framework.ipynb</code></strong> and work through it end to end. You will assemble a <strong>Contoso customer support agent</strong> with every production concern wired in:</p>\n<ol class=\"cs-list\">\n<li><strong>Tool calling</strong> — look up order status and open support tickets.</li>\n<li><strong>RAG</strong> — answer policy questions from a knowledge base (Azure AI Search, with an in-memory fallback so the notebook runs without a Search resource).</li>\n<li><strong>Memory</strong> — remember the customer across turns of the conversation.</li>\n<li><strong>Model routing</strong> — a complexity classifier routes each request to a small or large model.</li>\n<li><strong>Response caching</strong> — repeated questions are served from cache.</li>\n<li><strong>Human approval</strong> — refunds above a threshold pause for human sign-off.</li>\n<li><strong>Evaluation pipeline</strong> — a small offline test set scores the agent and acts as a release gate.</li>\n<li><strong>Observability</strong> — OpenTelemetry tracing around every request.</li>\n</ol>\n<h3 id=\"ai-sec-15\" class=\"cs-h3\">Walkthrough</h3>\n<p>The notebook is organised so each production concern is a self-contained, runnable section. The heart of it is the routing-plus-caching request handler:</p>\n<pre class=\"cs-code\"><code>async def handle_support_request(query: str, customer_id: str) -&gt; str:\n    # 1. Serve from cache when we can.\n    cached = response_cache.get(normalize(query))\n    if cached:\n        return cached\n\n    # 2. Route by complexity to control cost.\n    model = &quot;gpt-5-nano&quot; if is_simple(query) else &quot;gpt-5-mini&quot;\n\n    # 3. Run the agent inside a trace span for observability.\n    with tracer.start_as_current_span(&quot;support_request&quot;) as span:\n        span.set_attribute(&quot;routed.model&quot;, model)\n        span.set_attribute(&quot;customer.id&quot;, customer_id)\n        response = await support_agent.run(query, model=model)\n\n    # 4. Cache and return.\n    response_cache.set(normalize(query), response.text)\n    return response.text</code></pre>\n<p>The evaluation gate that guards a release looks like this:</p>\n<pre class=\"cs-code\"><code>async def evaluation_gate(agent, test_cases, threshold: float = 0.8) -&gt; bool:\n    passed = 0\n    for case in test_cases:\n        result = await agent.run(case[&quot;input&quot;])\n        if score_response(result.text, case[&quot;expected&quot;]) &gt;= 0.8:\n            passed += 1\n    pass_rate = passed / len(test_cases)\n    print(f&quot;Evaluation pass rate: {pass_rate:.0%} (gate: {threshold:.0%})&quot;)\n    return pass_rate &gt;= threshold  # only deploy if the gate passes</code></pre>\n<p>Read every line — the notebook keeps the primitives deliberately small so nothing is hidden behind a framework call.</p>\n<h2 id=\"ai-sec-16\" class=\"cs-h2\">Validating a Deployed Agent with Smoke Tests</h2>\n<p>The evaluation gate above runs <em>offline</em> against your agent object. Once the agent is deployed as a Hosted Agent, you need one more, even cheaper check: <strong>is the deployed endpoint actually answering?</strong></p>\n<p>Deploying \"successfully\" only proves the control plane accepted the definition — it does not prove the agent responds. A missing dependency, a bad model routing, or an expired connection can leave a green deployment that returns nothing. A <strong>smoke test</strong> catches that in seconds, on every deploy, without the cost of a full evaluation.</p>\n<p>This repository ships a ready-to-use smoke-test pipeline built on the <a href=\"https://github.com/marketplace/actions/ai-smoke-test\" target=\"_blank\" rel=\"noopener noreferrer\">AI Smoke Test</a> GitHub Action:</p>\n<ul class=\"cs-list\">\n<li><strong>Catalog</strong> — <strong><code>tests/lesson-16-smoke-tests.json</code></strong> contains prompts and assertions for the Contoso support agent (grounded policy answers, an order lookup, staying on-topic, and multi-turn thread continuity). Catalogs for other lessons' agents live alongside it — see <strong><code>tests/README.md</code></strong>.</li>\n<li><strong>Workflow</strong> — <strong><code>.github/workflows/smoke-test.yml</code></strong> logs in with Azure OIDC and POSTs each prompt to the agent's Responses endpoint, failing the job on any assertion miss.</li>\n</ul>\n<pre class=\"cs-code\"><code>- name: Smoke-test hosted agent\n  uses: JFolberth/ai-smoketest@v1\n  with:\n    project_endpoint: ${{ inputs.project_endpoint }}\n    agent_name: ContosoSupportAgent\n    tests_file: tests/lesson-16-smoke-tests.json</code></pre>\n<p>Run it from the <strong>Actions</strong> tab once your agent is deployed, supplying your Foundry project endpoint and agent name. The federated identity needs the <strong>Azure AI User</strong> role at Foundry project scope. Think of the layers as a pyramid: smoke tests (reachable and responding?) run on every deploy, offline evaluation (good enough to ship?) runs before promotion, and online evaluation (how is it doing in the wild?) runs continuously.</p>\n<h2 id=\"ai-sec-17\" class=\"cs-h2\">Knowledge Check</h2>\n<p>Test your understanding before moving to the assignment.</p>\n<p><strong>1. Roughly how much of a production agent is \"the model,\" and what is the rest?</strong></p>\n<p>The model is a minority of the system — often cited as around 20%. The rest is the operational skeleton: hosting and versioning, identity and RBAC, externalised state, failure handling, cost tracking, evaluation, and human-in-the-loop controls. Moving to production is mostly about building everything <em>around</em> the reasoning loop.</p>\n<p><strong>2. When would you choose a Hosted Agent over a client-hosted agent?</strong></p>\n<p>When you want a managed runtime with built-in durability (threads that persist and can resume), observability, content safety, and RBAC, and you are willing to trade some low-level control of the reasoning loop for less operational surface area. Client-hosted is preferable when you need full control over the loop or are embedding the agent in an existing backend.</p>\n<p><strong>3. Why must a scalable agent be stateless in its own process memory?</strong></p>\n<p>So any instance can handle any request, which is what allows horizontal scaling without sticky sessions. Per-user conversation state is externalised to a thread store or memory service. If state lived in process memory, you would lose it on restart and could not distribute load freely.</p>\n<p><strong>4. What problem does model routing solve, and how does it relate to evaluation?</strong></p>\n<p>Routing sends simple requests to a small, cheap, fast model and reserves the large model for genuine reasoning, controlling both latency and cost. It relates to evaluation because evaluation is what <em>proves</em> the small model is good enough for a class of requests — routing without evaluation is guessing.</p>\n<p><strong>5. What is an \"evaluation gate\" and where does it sit in the lifecycle?</strong></p>\n<p>An evaluation gate runs an offline test set against a new agent version and blocks deployment unless the pass rate clears a threshold. It sits between \"version\" and \"deploy\" in the lifecycle, making quality a precondition for release rather than something you check after shipping.</p>\n<p><strong>6. Why should an MCP server be treated as an untrusted boundary in production?</strong></p>\n<p>Because it is an external dependency your agent calls into. You should pin its version, run it with a scoped identity, validate its outputs, rate-limit it, and never expose secrets to it — the same discipline you apply to any third-party dependency. Its outputs flow into your agent's reasoning, so unvalidated trust is a security risk.</p>\n<p><strong>7. Which single change usually has the biggest impact on production agent cost, and why?</strong></p>\n<p>Right-sizing the model — using the smallest model that still passes your evaluation gate. Cost is dominated by tokens, and a smaller model that meets the quality bar is almost always cheaper than a larger one. Caching and routing then reduce cost further, but choosing the right base model has the largest first-order effect.</p>\n<p><strong>8. What role do span attributes like <code>customer.tier</code> and <code>routed.model</code> play in observability?</strong></p>\n<p>They turn raw traces into answerable business questions. Without attributes you have a wall of spans; with them you can ask \"are enterprise customers being routed to the small model too often?\" or \"which model handles our slowest requests?\" Attributes are how you slice telemetry by the dimensions that matter to your operation.</p>\n<h2 id=\"ai-sec-18\" class=\"cs-h2\">Assignment</h2>\n<p>Take the customer support agent from the lab and harden it for a specific scenario: <strong>a subscription billing support agent for a SaaS company.</strong></p>\n<p>Your submission should:</p>\n<ol class=\"cs-list\">\n<li><strong>Replace the tools</strong> with billing-relevant ones: <code>get_subscription_status</code>, <code>get_invoice</code>, and <code>issue_credit</code> (credits above $50 require human approval).</li>\n<li><strong>Add three RAG documents</strong> covering the company's refund policy, billing cycle, and cancellation policy.</li>\n<li><strong>Extend the evaluation set</strong> to at least eight cases, including at least two that <em>should</em> trigger the human-approval path, and confirm your evaluation gate correctly passes or fails.</li>\n<li><strong>Add one cost report</strong>: after running ten mixed queries through the agent, print how many went to the small model, how many to the large model, and how many were served from cache.</li>\n</ol>\n<p>Write a short paragraph (in a markdown cell) explaining which model-routing rule you chose and how you would validate it with real traffic. There is no single correct answer — you are being assessed on whether the production concerns are wired together coherently.</p>\n<h2 id=\"ai-sec-19\" class=\"cs-h2\">Summary</h2>\n<p>In this lesson you moved an agent from prototype to production with Microsoft Foundry:</p>\n<ul class=\"cs-list\">\n<li>The jump to production is mostly about the <strong>operational skeleton</strong> around the model — hosting, identity, state, failure handling, cost, quality, and trust.</li>\n<li>You learned the three <strong>deployment patterns</strong> — client-hosted, Hosted Agents, and Agent Workflows — and when each fits.</li>\n<li>You walked the <strong>agent lifecycle</strong>, where offline <strong>evaluation acts as a release gate</strong> and online observability feeds failures back into the test set.</li>\n<li>You applied <strong>scaling strategies</strong> — stateless design, model routing, caching, and bounded concurrency — and connected them to <strong>cost optimisation</strong>.</li>\n<li>You wired in <strong>enterprise controls</strong>: RBAC, human-in-the-loop approval, and production-safe MCP integration.</li>\n<li>You built a <strong>production-ready customer support agent</strong> that ties every one of these concerns together in runnable code.</li>\n</ul>\n<p>The next lesson takes the opposite journey: instead of scaling agents up into the cloud, you will bring them <em>down</em> onto a single developer machine and run them entirely locally.</p>\n<h2 id=\"ai-sec-20\" class=\"cs-h2\">Additional Resources</h2>\n<ul class=\"cs-list\">\n<li>&lt;a href=\"https://learn.microsoft.com/azure/ai-foundry/what-is-azure-ai-foundry\" target=\"_blank\"&gt;Microsoft Foundry documentation&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/azure/ai-foundry/agents/overview\" target=\"_blank\"&gt;Microsoft Foundry Agent Service overview&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/en-us/agent-framework/overview/?wt.mc_id=youtube_26688_organicsocial_reactor&amp;pivots=programming-language-python\" target=\"_blank\"&gt;Microsoft Agent Framework&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/en-us/azure/ai-foundry/openai/concepts/model-router\" target=\"_blank\"&gt;Model Router in Microsoft Foundry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/azure/search/search-what-is-azure-search\" target=\"_blank\"&gt;Azure AI Search&lt;/a&gt;</li>\n<li>&lt;a href=\"https://opentelemetry.io/\" target=\"_blank\"&gt;OpenTelemetry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://github.com/marketplace/actions/ai-smoke-test\" target=\"_blank\"&gt;AI Smoke Test GitHub Action&lt;/a&gt;</li>\n<li>&lt;a href=\"https://modelcontextprotocol.io/\" target=\"_blank\"&gt;Model Context Protocol (MCP)&lt;/a&gt;</li>\n</ul>\n<h2 id=\"ai-sec-21\" class=\"cs-h2\">Previous Lesson</h2>\n<p><strong>Building Computer Use Agents (CUA)</strong></p>\n<h2 id=\"ai-sec-22\" class=\"cs-h2\">Next Lesson</h2>\n<p><strong>Creating Local AI Agents</strong></p>"}, "vi": {"title": "Triển khai Các Tác Nhân Có Khả Năng Mở Rộng với Microsoft Foundry", "sections": [{"id": "ai-sec-1", "level": 2, "title": "Giới thiệu"}, {"id": "ai-sec-2", "level": 2, "title": "Mục Tiêu Học Tập"}, {"id": "ai-sec-3", "level": 2, "title": "Yêu Cầu Tiên Quyết"}, {"id": "ai-sec-4", "level": 2, "title": "Từ Nguyên Mẫu đến Sản Xuất: Điều Gì Thực Sự Thay Đổi"}, {"id": "ai-sec-5", "level": 2, "title": "Mẫu Triển Khai Tác Nhân"}, {"id": "ai-sec-6", "level": 3, "title": "1. Tác Nhân Lưu Trữ Trên Khách Hàng"}, {"id": "ai-sec-7", "level": 3, "title": "2. Tác Nhân Được Lưu Trữ (Dịch vụ Tác nhân Foundry)"}, {"id": "ai-sec-8", "level": 3, "title": "3. Quy Trình Tác Nhân"}, {"id": "ai-sec-9", "level": 2, "title": "Vòng Đời Tác Nhân trên Microsoft Foundry"}, {"id": "ai-sec-10", "level": 2, "title": "Chiến Lược Mở Rộng Quy Mô"}, {"id": "ai-sec-11", "level": 2, "title": "Khả Năng Quan Sát Trong Môi Trường Sản Xuất"}, {"id": "ai-sec-12", "level": 2, "title": "Tối Ưu Hóa Chi Phí"}, {"id": "ai-sec-13", "level": 2, "title": "Cân Nhắc Khi Triển Khai Doanh Nghiệp"}, {"id": "ai-sec-14", "level": 2, "title": "Phòng Lab Thực Hành: Tác Nhân Hỗ Trợ Khách Hàng Sẵn Sàng Cho Sản Xuất"}, {"id": "ai-sec-15", "level": 3, "title": "Hướng Dẫn"}, {"id": "ai-sec-16", "level": 2, "title": "Xác Thực Tác Nhân Đã Triển Khai với Các Bài Kiểm Tra Khói"}, {"id": "ai-sec-17", "level": 2, "title": "Kiểm tra kiến thức"}, {"id": "ai-sec-18", "level": 2, "title": "Bài tập"}, {"id": "ai-sec-19", "level": 2, "title": "Tóm tắt"}, {"id": "ai-sec-20", "level": 2, "title": "Tài nguyên bổ sung"}, {"id": "ai-sec-21", "level": 2, "title": "Bài học trước"}, {"id": "ai-sec-22", "level": 2, "title": "Bài học tiếp"}], "html": "<h1 id=\"ai-sec-1\" class=\"cs-h1\">Triển khai Các Tác Nhân Có Khả Năng Mở Rộng với Microsoft Foundry</h1>\n<blockquote class=\"cs-quote\">[Figure: Triển khai Các Tác Nhân Có Khả Năng Mở Rộng]</blockquote>\n<p>Cho đến thời điểm này trong khóa học, bạn đã xây dựng các tác nhân chạy trên laptop của bạn, bên trong một notebook, được điều khiển bởi <code>az login</code> và một vài biến môi trường. Đó chính xác là cách đúng để học. Nhưng đó không phải là cách đúng để chạy một tác nhân mà hàng nghìn khách hàng phụ thuộc vào lúc 3 giờ sáng.</p>\n<p>Bài học này nói về khoảng cách giữa \"nó hoạt động trên máy tôi\" và \"nó hoạt động, đáng tin cậy và tiết kiệm, trong môi trường sản xuất.\" Chúng tôi đóng khoảng cách đó bằng cách sử dụng <strong>Microsoft Foundry</strong> và <strong>Dịch vụ Tác nhân Microsoft Foundry</strong>, và chúng tôi làm điều đó bằng cách xây dựng một tác nhân hỗ trợ khách hàng thực sự có các công cụ, truy xuất, bộ nhớ, đánh giá và giám sát.</p>\n<h2 id=\"ai-sec-1\" class=\"cs-h2\">Giới thiệu</h2>\n<p>Bài học này sẽ bao gồm:</p>\n<ul class=\"cs-list\">\n<li>Sự khác biệt giữa <strong>tác nhân nguyên mẫu</strong> và <strong>tác nhân được triển khai</strong>, và tại sao việc chuyển đổi chủ yếu liên quan đến mọi thứ <em>xung quanh</em> mô hình.</li>\n<li><strong>Mẫu triển khai</strong> cho các tác nhân: được lưu trữ trên máy khách, được lưu trữ dịch vụ (Tác nhân được lưu trữ), và được phối hợp theo quy trình làm việc.</li>\n<li><strong>Vòng đời tác nhân</strong> trên Microsoft Foundry — tạo, phiên bản, triển khai, đánh giá, quan sát, ngưng sử dụng.</li>\n<li><strong>Chiến lược mở rộng quy mô</strong>: định tuyến mô hình, lưu bộ nhớ đệm, đồng thời, và thiết kế không trạng thái.</li>\n<li><strong>Khả năng quan sát</strong> với OpenTelemetry và theo dõi Foundry.</li>\n<li><strong>Tối ưu hóa chi phí</strong> thông qua lựa chọn mô hình, định tuyến và các cửa kiểm tra đánh giá.</li>\n<li><strong>Cân nhắc doanh nghiệp</strong>: quản trị, phê duyệt bởi con người, và vận hành máy chủ MCP an toàn trong môi trường sản xuất.</li>\n</ul>\n<h2 id=\"ai-sec-2\" class=\"cs-h2\">Mục Tiêu Học Tập</h2>\n<p>Sau khi hoàn thành bài học này, bạn sẽ biết cách:</p>\n<ul class=\"cs-list\">\n<li>Chọn mẫu triển khai phù hợp cho một tải công việc của tác nhân.</li>\n<li>Triển khai một tác nhân tới Dịch vụ Tác nhân Microsoft Foundry để nó có phiên bản, được quản trị và có thể quan sát được.</li>\n<li>Thêm công cụ theo dõi cho tác nhân và nối dây một quy trình đánh giá chạy trước mỗi lần phát hành.</li>\n<li>Áp dụng định tuyến mô hình và bộ nhớ đệm để giữ độ trễ và chi phí trong tầm kiểm soát khi mở rộng quy mô.</li>\n<li>Thêm cửa phê duyệt của con người cho các hành động rủi ro cao và tích hợp máy chủ MCP theo cách an toàn cho sản xuất.</li>\n</ul>\n<h2 id=\"ai-sec-3\" class=\"cs-h2\">Yêu Cầu Tiên Quyết</h2>\n<p>Bài học này giả định bạn đã hoàn thành các bài học trước và thành thạo:</p>\n<ul class=\"cs-list\">\n<li>Xây dựng các tác nhân với <strong>Microsoft Agent Framework</strong> (Bài học 14).</li>\n<li><strong>Sử dụng Công Cụ</strong> (Bài học 4) và <strong>Agentic RAG</strong> (Bài học 5).</li>\n<li><strong>Bộ Nhớ Tác Nhân</strong> (Bài học 13) và <strong>Giao Thức Agentic / MCP</strong> (Bài học 11).</li>\n<li><strong>Khả Năng Quan Sát và Đánh Giá</strong> (Bài học 10) — bài học này xây dựng trực tiếp trên đó.</li>\n</ul>\n<p>Bạn cũng cần:</p>\n<ul class=\"cs-list\">\n<li>Một <strong>đăng ký Azure</strong> và một <strong>dự án Microsoft Foundry</strong> với ít nhất một mô hình trò chuyện đã được triển khai.</li>\n<li><strong>Azure CLI</strong> đã xác thực (<code>az login</code>).</li>\n<li>Python 3.12+ và các gói trong kho lưu trữ <strong><code>requirements.txt</code></strong>.</li>\n</ul>\n<h2 id=\"ai-sec-4\" class=\"cs-h2\">Từ Nguyên Mẫu đến Sản Xuất: Điều Gì Thực Sự Thay Đổi</h2>\n<p>Một tác nhân nguyên mẫu và tác nhân sản xuất chia sẻ cùng vòng lặp chính — suy luận, gọi công cụ, phản hồi. Điều thay đổi là mọi thứ bao quanh vòng lặp đó. Mô hình chỉ chiếm khoảng 20% của tác nhân sản xuất; 80% còn lại là bộ khung vận hành.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th>Mối Quan Tâm</th><th>Nguyên Mẫu</th><th>Sản Xuất</th></tr></thead><tbody>\n<tr><td><strong>Lưu trữ</strong></td><td>Chạy trong notebook của bạn</td><td>Chạy như một dịch vụ lưu trữ, có phiên bản và triển khai dần dần</td></tr>\n<tr><td><strong>Danh tính</strong></td><td>Mã token <code>az login</code> của bạn</td><td>Danh tính được quản lý với RBAC có phạm vi</td></tr>\n<tr><td><strong>Trạng thái</strong></td><td>Trong bộ nhớ, mất khi khởi động lại</td><td>Bên ngoài (cửa hàng luồng, dịch vụ bộ nhớ)</td></tr>\n<tr><td><strong>Thất bại</strong></td><td>Bạn thấy lại traceback</td><td>Thử lại, dự phòng, thư chết, cảnh báo</td></tr>\n<tr><td><strong>Chi phí</strong></td><td>\"Chỉ vài xu\"</td><td>Theo dõi trên từng yêu cầu, định tuyến, bộ nhớ đệm, ngân sách</td></tr>\n<tr><td><strong>Chất lượng</strong></td><td>Bạn xem xét đầu ra</td><td>Đánh giá tự động trước mỗi lần phát hành</td></tr>\n<tr><td><strong>Tin cậy</strong></td><td>Bạn phê duyệt mọi hành động</td><td>Chính sách + con người tham gia trong các hành động rủi ro</td></tr>\n</tbody></table></div>\n<p>Hãy ghi nhớ bảng này. Mỗi phần dưới đây tương ứng với một trong những dòng này.</p>\n<h2 id=\"ai-sec-5\" class=\"cs-h2\">Mẫu Triển Khai Tác Nhân</h2>\n<p>Có ba mẫu bạn sẽ sử dụng, thường kết hợp với nhau.</p>\n<h3 id=\"ai-sec-6\" class=\"cs-h3\">1. Tác Nhân Lưu Trữ Trên Khách Hàng</h3>\n<p>Đối tượng tác nhân sống bên trong quá trình ứng dụng <em>của bạn</em>. Mã của bạn gọi nhà cung cấp mô hình trực tiếp; vòng suy luận chạy trong dịch vụ của bạn. Đây là những gì mọi bài học trước đã thực hiện.</p>\n<ul class=\"cs-list\">\n<li><strong>Sử dụng khi</strong> bạn cần kiểm soát hoàn toàn vòng, phần mềm trung gian tùy chỉnh, hoặc bạn nhúng tác nhân bên trong backend hiện có.</li>\n<li><strong>Đổi lại</strong>: bạn tự chịu trách nhiệm về mở rộng quy mô, trạng thái và độ bền.</li>\n</ul>\n<h3 id=\"ai-sec-7\" class=\"cs-h3\">2. Tác Nhân Được Lưu Trữ (Dịch vụ Tác nhân Foundry)</h3>\n<p>Tác nhân được <em>đăng ký như một tài nguyên</em> trong Microsoft Foundry. Foundry lưu trữ vòng suy luận, lưu trữ các luồng, thực thi an toàn nội dung và RBAC, và làm cho tác nhân hiển thị trong cổng Foundry. Ứng dụng của bạn trở thành một khách mỏng chỉ tạo luồng và đọc phản hồi.</p>\n<ul class=\"cs-list\">\n<li><strong>Sử dụng khi</strong> bạn muốn độ bền, khả năng quan sát tích hợp sẵn, quản trị và giảm bớt bề mặt vận hành.</li>\n<li><strong>Đổi lại</strong>: ít kiểm soát cấp thấp hơn đổi lấy một môi trường runtime được quản lý.</li>\n</ul>\n<h3 id=\"ai-sec-8\" class=\"cs-h3\">3. Quy Trình Tác Nhân</h3>\n<p>Nhiều tác nhân (và công cụ) được ghép thành một đồ thị với luồng điều khiển rõ ràng — các bước tuần tự, phân nhánh, nút phê duyệt của con người, và các điểm kiểm tra bền vững có thể tạm dừng và tiếp tục. Đây là khả năng <strong>Quy Trình làm việc</strong> của Microsoft Agent Framework áp dụng ở quy mô triển khai.</p>\n<ul class=\"cs-list\">\n<li><strong>Sử dụng khi</strong> một nhiệm vụ đơn kéo dài qua nhiều tác nhân chuyên biệt hoặc đòi hỏi bước phê duyệt ở giữa.</li>\n<li><strong>Đổi lại</strong>: nhiều phần chuyển động hơn; cần khả năng quan sát cấp phối hợp.</li>\n</ul>\n<pre class=\"cs-code\"><code>flowchart TB\n    subgraph P1[Client-Hosted]\n        A1[Your App Process] --&gt; M1[Model Provider]\n    end\n    subgraph P2[Hosted Agent]\n        A2[Thin Client] --&gt; F2[Foundry Agent Service]\n        F2 --&gt; M2[Model + Tools + Thread Store]\n    end\n    subgraph P3[Agent Workflow]\n        A3[Orchestrator] --&gt; S1[Triage Agent]\n        S1 --&gt; S2[Resolver Agent]\n        S2 --&gt; H[Human Approval Node]\n        H --&gt; S3[Action Agent]\n    end</code></pre>\n<h2 id=\"ai-sec-9\" class=\"cs-h2\">Vòng Đời Tác Nhân trên Microsoft Foundry</h2>\n<p>Triển khai một tác nhân không phải là một thao tác <code>push</code> một lần. Đó là một vòng lặp, và nó rất giống chu trình phát hành phần mềm bởi vì đúng là như vậy.</p>\n<pre class=\"cs-code\"><code>flowchart LR\n    Create[Create / Author] --&gt; Version[Version]\n    Version --&gt; Evaluate[Evaluate offline]\n    Evaluate --&gt;|passes gate| Deploy[Deploy hosted]\n    Evaluate --&gt;|fails gate| Create\n    Deploy --&gt; Observe[Observe online]\n    Observe --&gt; Improve[Collect failures]\n    Improve --&gt; Create\n    Deploy --&gt; Retire[Retire old version]</code></pre>\n<p>Ý tưởng chính, tiếp nối từ <strong>Bài học 10</strong>: <strong>đánh giá offline là một cửa kiểm, không phải là điều được nghĩ đến sau cùng.</strong> Phiên bản tác nhân mới không được phát hành trừ khi vượt qua các ngưỡng đánh giá của bạn. Khả năng quan sát online sau đó đưa các lỗi thực tế trở lại bộ kiểm tra offline của bạn. Đó là toàn bộ vòng lặp.</p>\n<h2 id=\"ai-sec-10\" class=\"cs-h2\">Chiến Lược Mở Rộng Quy Mô</h2>\n<p>Mở rộng một tác nhân khác với mở rộng API web không trạng thái, vì mỗi yêu cầu có thể kích hoạt nhiều lần gọi mô hình và công cụ tốn kém. Bốn kỹ thuật chịu phần lớn lượng tải.</p>\n<p><strong>Xử lý yêu cầu không trạng thái.</strong> Không giữ trạng thái người dùng riêng trong bộ nhớ quá trình của bạn. Lưu các luồng hội thoại trong cửa hàng luồng Foundry hoặc dịch vụ bộ nhớ để bất kỳ phiên bản nào cũng có thể xử lý bất kỳ yêu cầu nào. Đây là điều cho phép bạn mở rộng theo chiều ngang — thêm phiên bản, không cần phiên làm việc cố định.</p>\n<p><strong>Định tuyến mô hình.</strong> Không phải mọi yêu cầu đều cần mô hình có khả năng cao nhất (và đắt nhất) của bạn. Định tuyến các yêu cầu đơn giản — phân loại ý định, trả lời ngắn gọn các câu hỏi thực tế — đến một mô hình nhỏ, nhanh và dành mô hình lớn cho suy luận thực sự. <strong>Bộ định tuyến Mô hình</strong> của Foundry có thể làm điều này cho bạn, hoặc bạn có thể tự triển khai một bộ phân loại nhẹ. Bạn sẽ xây dựng phiên bản DIY trong phòng lab.</p>\n<p><strong>Bộ nhớ đệm phản hồi.</strong> Nhiều truy vấn hỗ trợ gần như trùng lặp (\"làm thế nào để tôi đặt lại mật khẩu?\"). Lưu câu trả lời cho các câu hỏi phổ biến và phục vụ mà không cần gọi đến mô hình. Ngay cả tỷ lệ trúng bộ nhớ đệm khiêm tốn cũng giúp cắt giảm đáng kể chi phí và độ trễ.</p>\n<p><strong>Đồng thời và áp lực ngược.</strong> Nhà cung cấp mô hình có giới hạn tốc độ. Giới hạn đồng thời, sử dụng thử lại với lùi lại số mũ, và xử lý thất bại một cách nhẹ nhàng (phản hồi \"chúng tôi đang xử lý\" trong hàng đợi tốt hơn mã lỗi 500).</p>\n<pre class=\"cs-code\"><code>flowchart LR\n    Q[User query] --&gt; C{Cache hit?}\n    C --&gt;|yes| R[Return cached answer]\n    C --&gt;|no| Router{Complexity?}\n    Router --&gt;|simple| SLM[Small model]\n    Router --&gt;|complex| LLM[Large model]\n    SLM --&gt; Out[Response]\n    LLM --&gt; Out\n    Out --&gt; Store[Cache + trace]</code></pre>\n<h2 id=\"ai-sec-11\" class=\"cs-h2\">Khả Năng Quan Sát Trong Môi Trường Sản Xuất</h2>\n<p>Bạn không thể vận hành thứ bạn không thể quan sát. Như đã đề cập trong Bài học 10, Microsoft Agent Framework tạo ra các dấu vết <strong>OpenTelemetry</strong> bản địa — mọi lần gọi mô hình, khởi chạy công cụ, và bước phối hợp trở thành một khoảng thời gian theo dõi. Trong môi trường sản xuất, bạn xuất các khoảng thời gian đó đến Microsoft Foundry (hoặc bất kỳ backend tương thích OTel nào) để bạn có thể:</p>\n<ul class=\"cs-list\">\n<li>Theo dõi một đơn khiếu nại khách hàng từ đầu đến cuối qua mọi lần gọi mô hình và công cụ.</li>\n<li>Theo dõi độ trễ p50/p95 và chi phí trên mỗi yêu cầu theo thời gian.</li>\n<li>Cảnh báo khi xảy ra đột biến tỷ lệ lỗi và bất thường về chi phí trước khi người dùng (hoặc đội tài chính của bạn) nhận thấy.</li>\n</ul>\n<pre class=\"cs-code\"><code>from agent_framework.observability import get_tracer\n\ntracer = get_tracer()\n\nwith tracer.start_as_current_span(&quot;support_request&quot;) as span:\n    span.set_attribute(&quot;customer.tier&quot;, &quot;enterprise&quot;)\n    span.set_attribute(&quot;routed.model&quot;, &quot;gpt-5-nano&quot;)\n    # agent execution is traced automatically inside this span</code></pre>\n<p>Các thuộc tính như <code>customer.tier</code> và <code>routed.model</code> giúp biến một lượng lớn dấu vết thành các câu hỏi có thể trả lời được (\"khách hàng doanh nghiệp có bị định tuyến sang mô hình nhỏ quá thường xuyên không?\").</p>\n<h2 id=\"ai-sec-12\" class=\"cs-h2\">Tối Ưu Hóa Chi Phí</h2>\n<p>Chi phí trong tác nhân sản xuất bị chi phối bởi token. Ba cần gạt, theo thứ tự tác động:</p>\n<ol class=\"cs-list\">\n<li><strong>Chọn kích thước mô hình phù hợp.</strong> Một mô hình nhỏ vượt qua cửa kiểm đánh giá của bạn hầu như luôn rẻ hơn mô hình lớn cũng vượt qua. Dùng đánh giá để <em>chứng minh</em> mô hình nhỏ đủ tốt thay vì mặc định chọn mô hình lớn nhất để đề phòng.</li>\n<li><strong>Định tuyến theo độ phức tạp.</strong> Như trên — chỉ trả giá mô hình lớn cho các yêu cầu cần suy luận mô hình lớn.</li>\n<li><strong>Lưu bộ nhớ đệm tích cực.</strong> Cuộc gọi mô hình rẻ nhất là cuộc gọi bạn không bao giờ thực hiện.</li>\n</ol>\n<p>Các cửa kiểm đánh giá và kiểm soát chi phí là cùng một kỹ thuật nhìn từ hai góc độ: đánh giá cho bạn <em>mức chất lượng tối thiểu</em>, định tuyến và lưu bộ nhớ đệm giữ bạn càng gần chi phí của mức đó càng tốt.</p>\n<h2 id=\"ai-sec-13\" class=\"cs-h2\">Cân Nhắc Khi Triển Khai Doanh Nghiệp</h2>\n<p><strong>Quản trị.</strong> Tác nhân lưu trữ kế thừa RBAC, an toàn nội dung và ghi nhật ký kiểm toán của Foundry. Cung cấp cho từng tác nhân một danh tính được quản lý với đặc quyền tối thiểu cần thiết — quyền truy cập chỉ đọc vào cơ sở tri thức, quyền truy cập có phạm vi vào API vé hỗ trợ, không hơn.</p>\n<p><strong>Con người tham gia vào vòng lặp.</strong> Một số hành động có hậu quả quá lớn để tự động hoàn toàn — hoàn tiền, xóa tài khoản, chuyển tiếp đến đội pháp lý. Microsoft Agent Framework hỗ trợ các công cụ <strong>cần phê duyệt</strong>: tác nhân đề xuất hành động, thực thi tạm dừng, con người phê duyệt hoặc từ chối, rồi quy trình làm việc tiếp tục. Bạn đã thấy nguyên thủy này trong <strong>Bài học 6</strong>; bây giờ bạn triển khai nó.</p>\n<p><strong>MCP trong sản xuất.</strong> <strong>MCP</strong> cho phép tác nhân của bạn sử dụng công cụ bên ngoài qua một giao diện chuẩn. Trong sản xuất, coi mỗi máy chủ MCP là một ranh giới không tin cậy: cố định phiên bản máy chủ, chạy nó với danh tính có phạm vi, kiểm tra đầu ra, và không bao giờ tiết lộ bí mật cho nó. Máy chủ MCP là một phụ thuộc, và phụ thuộc được vá lỗi, kiểm toán và giới hạn tốc độ.</p>\n<pre class=\"cs-code\"><code>flowchart TB\n    subgraph Dev[Development Architecture]\n        D1[Notebook] --&gt; D2[Agent Framework]\n        D2 --&gt; D3[Model Provider]\n        D2 --&gt; D4[Local tools]\n    end\n    subgraph Deploy[Deployment Architecture]\n        E1[CI pipeline] --&gt; E2[Evaluation gate]\n        E2 --&gt;|pass| E3[Foundry Agent Service]\n        E3 --&gt; E4[Versioned hosted agent]\n    end\n    subgraph Run[Runtime Architecture]\n        F1[Client app] --&gt; F2[Hosted agent]\n        F2 --&gt; F3[Model Router]\n        F2 --&gt; F4[Azure AI Search RAG]\n        F2 --&gt; F5[Memory service]\n        F2 --&gt; F6[MCP tools]\n        F2 --&gt; F7[OTel -&gt; Foundry tracing]\n        F2 --&gt; F8[Human approval]\n    end</code></pre>\n<p>Ba sơ đồ đó — phát triển, triển khai, thời gian chạy — là cùng một tác nhân ở ba giai đoạn cuộc đời nó. Phòng lab tiếp theo sẽ hướng dẫn bạn xây dựng nó.</p>\n<h2 id=\"ai-sec-14\" class=\"cs-h2\">Phòng Lab Thực Hành: Tác Nhân Hỗ Trợ Khách Hàng Sẵn Sàng Cho Sản Xuất</h2>\n<p>Mở <strong><code>code_samples/16-python-agent-framework.ipynb</code></strong> và làm theo từng bước. Bạn sẽ lắp ráp một <strong>tác nhân hỗ trợ khách hàng Contoso</strong> với mọi mối quan tâm về sản xuất được tích hợp:</p>\n<ol class=\"cs-list\">\n<li><strong>Gọi công cụ</strong> — tra cứu trạng thái đơn hàng và mở vé hỗ trợ.</li>\n<li><strong>RAG</strong> — trả lời câu hỏi chính sách từ cơ sở tri thức (Azure AI Search, với việc dự phòng trong bộ nhớ để notebook chạy mà không cần tài nguyên Search).</li>\n<li><strong>Bộ nhớ</strong> — nhớ khách hàng qua các lượt hội thoại.</li>\n<li><strong>Định tuyến mô hình</strong> — một bộ phân loại độ phức tạp định tuyến mỗi yêu cầu đến mô hình nhỏ hoặc lớn.</li>\n<li><strong>Lưu bộ nhớ đệm phản hồi</strong> — các câu hỏi lặp lại được phục vụ từ bộ nhớ đệm.</li>\n<li><strong>Phê duyệt của con người</strong> — hoàn tiền vượt ngưỡng dừng lại để phê duyệt của con người.</li>\n<li><strong>Đường ống đánh giá</strong> — một bộ kiểm tra offline nhỏ chấm điểm tác nhân và đóng vai trò cửa kiểm phát hành.</li>\n<li><strong>Khả năng quan sát</strong> — theo dõi OpenTelemetry quanh mỗi yêu cầu.</li>\n</ol>\n<h3 id=\"ai-sec-15\" class=\"cs-h3\">Hướng Dẫn</h3>\n<p>Notebook được tổ chức sao cho mỗi mối quan tâm sản xuất là một phần riêng biệt, có thể chạy độc lập. Trọng tâm là trình xử lý yêu cầu kết hợp định tuyến và lưu bộ nhớ đệm:</p>\n<pre class=\"cs-code\"><code>async def handle_support_request(query: str, customer_id: str) -&gt; str:\n    # 1. Serve from cache when we can.\n    cached = response_cache.get(normalize(query))\n    if cached:\n        return cached\n\n    # 2. Route by complexity to control cost.\n    model = &quot;gpt-5-nano&quot; if is_simple(query) else &quot;gpt-5-mini&quot;\n\n    # 3. Run the agent inside a trace span for observability.\n    with tracer.start_as_current_span(&quot;support_request&quot;) as span:\n        span.set_attribute(&quot;routed.model&quot;, model)\n        span.set_attribute(&quot;customer.id&quot;, customer_id)\n        response = await support_agent.run(query, model=model)\n\n    # 4. Cache and return.\n    response_cache.set(normalize(query), response.text)\n    return response.text</code></pre>\n<p>Cửa kiểm đánh giá bảo vệ một lần phát hành trông như thế này:</p>\n<pre class=\"cs-code\"><code>async def evaluation_gate(agent, test_cases, threshold: float = 0.8) -&gt; bool:\n    passed = 0\n    for case in test_cases:\n        result = await agent.run(case[&quot;input&quot;])\n        if score_response(result.text, case[&quot;expected&quot;]) &gt;= 0.8:\n            passed += 1\n    pass_rate = passed / len(test_cases)\n    print(f&quot;Evaluation pass rate: {pass_rate:.0%} (gate: {threshold:.0%})&quot;)\n    return pass_rate &gt;= threshold  # only deploy if the gate passes</code></pre>\n<p>Đọc từng dòng — notebook giữ các nguyên mẫu nhỏ một cách có chủ đích để không có gì bị ẩn sau một lời gọi framework.</p>\n<h2 id=\"ai-sec-16\" class=\"cs-h2\">Xác Thực Tác Nhân Đã Triển Khai với Các Bài Kiểm Tra Khói</h2>\n<p>Cửa kiểm đánh giá ở trên chạy <em>offline</em> chống lại đối tượng tác nhân của bạn. Khi tác nhân được triển khai dưới dạng Tác nhân được lưu trữ, bạn cần một kiểm tra nữa, rẻ hơn: <strong>điểm cuối triển khai có thực sự trả lời không?</strong></p>\n<p>Triển khai \"thành công\" chỉ chứng minh mặt điều khiển chấp nhận định nghĩa — không chứng minh tác nhân trả lời. Thiếu phụ thuộc, định tuyến mô hình sai, hoặc kết nối hết hạn có thể để lại triển khai xanh nhưng không trả về gì. <strong>Kiểm tra khói</strong> phát hiện điều đó trong vài giây, trên mỗi lần triển khai, không tốn kém như đánh giá toàn diện.</p>\n<p>Kho lưu trữ này cung cấp đường ống kiểm tra khói sẵn dùng xây trên GitHub Action <a href=\"https://github.com/marketplace/actions/ai-smoke-test\" target=\"_blank\" rel=\"noopener noreferrer\">AI Smoke Test</a>:</p>\n<ul class=\"cs-list\">\n<li><strong>Danh mục</strong> — <strong><code>tests/lesson-16-smoke-tests.json</code></strong> chứa các lời nhắc và khẳng định cho tác nhân hỗ trợ Contoso (câu trả lời chính xác dựa trên chính sách, tra cứu đơn hàng, giữ đúng chủ đề, và tính liên tục hội thoại đa lượt). Các danh mục cho các tác nhân bài học khác nằm bên cạnh nó — xem <strong><code>tests/README.md</code></strong>.</li>\n<li><strong>Luồng công việc</strong> — <strong><code>.github/workflows/smoke-test.yml</code></strong> đăng nhập với Azure OIDC và gửi POST mỗi lời nhắc đến điểm cuối Responses của tác nhân, thất bại công việc nếu có bất kỳ khẳng định nào không đúng.</li>\n</ul>\n<pre class=\"cs-code\"><code>- name: Smoke-test hosted agent\n  uses: JFolberth/ai-smoketest@v1\n  with:\n    project_endpoint: ${{ inputs.project_endpoint }}\n    agent_name: ContosoSupportAgent\n    tests_file: tests/lesson-16-smoke-tests.json</code></pre>\n<p>Chạy nó từ tab <strong>Actions</strong> khi tác nhân của bạn đã được triển khai, cung cấp điểm cuối dự án Foundry và tên tác nhân. Danh tính liên kết cần có vai trò <strong>Azure AI User</strong> ở phạm vi dự án Foundry. Hãy nghĩ về các lớp như một hình chóp: kiểm tra sơ bộ (có thể truy cập và phản hồi?) chạy trên mỗi lần triển khai, đánh giá ngoại tuyến (đủ tốt để phát hành?) chạy trước khi thăng cấp, và đánh giá trực tuyến (nó hoạt động thế nào trong thực tế?) chạy liên tục.</p>\n<h2 id=\"ai-sec-17\" class=\"cs-h2\">Kiểm tra kiến thức</h2>\n<p>Kiểm tra hiểu biết của bạn trước khi chuyển sang bài tập.</p>\n<p><strong>1. Đại khái \"mô hình\" chiếm bao nhiêu phần trong một tác nhân sản xuất, và phần còn lại là gì?</strong></p>\n<p>Mô hình chiếm phần thiểu số của hệ thống — thường được trích dẫn khoảng 20%. Phần còn lại là bộ khung vận hành: lưu trữ và quản lý phiên bản, danh tính và RBAC, trạng thái bên ngoài, xử lý lỗi, theo dõi chi phí, đánh giá và các kiểm soát có người giám sát. Việc chuyển sang sản xuất chủ yếu là xây dựng mọi thứ <em>xung quanh</em> vòng suy luận.</p>\n<p><strong>2. Khi nào bạn chọn Tác nhân Hosted thay vì tác nhân do khách hàng lưu trữ?</strong></p>\n<p>Khi bạn muốn một môi trường runtime được quản lý với độ bền tích hợp (luồng chạy bền và có thể tiếp tục), khả năng quan sát, an toàn nội dung và RBAC, và bạn sẵn sàng đánh đổi một số quyền kiểm soát thấp hơn của vòng suy luận để giảm diện tích vận hành. Khách hàng lưu trữ thích hợp hơn khi bạn cần kiểm soát hoàn toàn vòng lặp hoặc nhúng tác nhân vào backend hiện có.</p>\n<p><strong>3. Tại sao một tác nhân có thể mở rộng phải không lưu trạng thái trong bộ nhớ tiến trình riêng của nó?</strong></p>\n<p>Để bất kỳ phiên bản nào cũng có thể xử lý bất cứ yêu cầu nào, điều này cho phép mở rộng ngang mà không cần phiên làm việc dính. Trạng thái hội thoại của từng người dùng được bên ngoài hóa vào kho lưu trữ luồng hoặc dịch vụ bộ nhớ. Nếu trạng thái tồn tại trong bộ nhớ tiến trình, bạn sẽ mất nó khi khởi động lại và không thể phân phối tải tự do.</p>\n<p><strong>4. Vấn đề mà định tuyến mô hình giải quyết là gì, và nó liên quan thế nào đến đánh giá?</strong></p>\n<p>Định tuyến chuyển những yêu cầu đơn giản đến một mô hình nhỏ, rẻ, nhanh và dự trữ mô hình lớn cho suy luận thật sự, kiểm soát cả độ trễ lẫn chi phí. Nó liên quan đến đánh giá vì đánh giá là thứ <em>chứng minh</em> mô hình nhỏ đủ tốt cho một loại yêu cầu — định tuyến không đánh giá chỉ là đoán mò.</p>\n<p><strong>5. Một \"cổng đánh giá\" là gì và nó nằm ở đâu trong vòng đời?</strong></p>\n<p>Một cổng đánh giá chạy bộ kiểm tra ngoại tuyến trên phiên bản tác nhân mới và chặn triển khai trừ khi tỷ lệ vượt qua vượt ngưỡng. Nó nằm giữa \"phiên bản\" và \"triển khai\" trong vòng đời, đặt chất lượng thành điều kiện tiên quyết cho phát hành thay vì thứ bạn kiểm tra sau khi phát hành.</p>\n<p><strong>6. Tại sao một máy chủ MCP nên được xem là biên giới không tin cậy trong sản xuất?</strong></p>\n<p>Vì nó là một phụ thuộc bên ngoài mà tác nhân của bạn gọi vào. Bạn nên đóng chặt phiên bản của nó, chạy nó với danh tính có phạm vi, xác thực đầu ra, giới hạn tốc độ và không bao giờ để lộ bí mật cho nó — kỷ luật tương tự như với bất kỳ phụ thuộc bên thứ ba nào. Đầu ra của nó chảy vào suy luận của tác nhân bạn, vì vậy tin tưởng không được xác thực là rủi ro bảo mật.</p>\n<p><strong>7. Thay đổi đơn lẻ nào thường ảnh hưởng lớn nhất đến chi phí tác nhân sản xuất, và tại sao?</strong></p>\n<p>Chọn kích thước mô hình phù hợp — sử dụng mô hình nhỏ nhất vẫn vượt cổng đánh giá của bạn. Chi phí bị chi phối bởi token, và mô hình nhỏ hơn mà đạt chất lượng thường rẻ hơn mô hình lớn. Bộ nhớ đệm và định tuyến tiếp tục giảm chi phí, nhưng chọn mô hình cơ sở đúng ảnh hưởng lớn nhất.</p>\n<p><strong>8. Thuộc tính span như <code>customer.tier</code> và <code>routed.model</code> có vai trò gì trong khả năng quan sát?</strong></p>\n<p>Chúng biến các dấu vết thô thành các câu hỏi kinh doanh có thể trả lời được. Không có thuộc tính, bạn chỉ có một bức tường các span; với chúng bạn có thể hỏi \"khách hàng doanh nghiệp có thường xuyên được định tuyến đến mô hình nhỏ không?\" hoặc \"mô hình nào xử lý các yêu cầu chậm nhất của chúng ta?\" Thuộc tính là cách bạn phân lát telemetry theo các chiều quan trọng với vận hành của bạn.</p>\n<h2 id=\"ai-sec-18\" class=\"cs-h2\">Bài tập</h2>\n<p>Lấy tác nhân hỗ trợ khách hàng từ phòng thí nghiệm và tăng cường nó cho một kịch bản cụ thể: <strong>tác nhân hỗ trợ thanh toán đăng ký cho một công ty SaaS.</strong></p>\n<p>Bản nộp của bạn nên:</p>\n<ol class=\"cs-list\">\n<li><strong>Thay thế các công cụ</strong> bằng những công cụ liên quan đến thanh toán: <code>get_subscription_status</code>, <code>get_invoice</code>, và <code>issue_credit</code> (tín dụng trên $50 cần sự phê duyệt của con người).</li>\n<li><strong>Thêm ba tài liệu RAG</strong> về chính sách hoàn tiền, chu kỳ thanh toán và chính sách hủy của công ty.</li>\n<li><strong>Mở rộng bộ đánh giá</strong> ít nhất tám trường hợp, bao gồm ít nhất hai trường hợp <em>nên</em> kích hoạt đường dẫn phê duyệt của con người, và xác nhận cổng đánh giá của bạn hoạt động đúng.</li>\n<li><strong>Thêm một báo cáo chi phí</strong>: sau khi chạy mười truy vấn hỗn hợp qua tác nhân, in ra số lượng truy vấn gửi tới mô hình nhỏ, mô hình lớn và số lượng truy vấn được phục vụ từ bộ nhớ đệm.</li>\n</ol>\n<p>Viết một đoạn ngắn (trong ô markdown) giải thích bạn chọn quy tắc định tuyến mô hình nào và cách bạn sẽ xác thực nó với lưu lượng thực. Không có câu trả lời đúng duy nhất — bạn sẽ được đánh giá dựa trên việc liệu các quan ngại về sản xuất có được kết nối một cách mạch lạc hay không.</p>\n<h2 id=\"ai-sec-19\" class=\"cs-h2\">Tóm tắt</h2>\n<p>Trong bài học này bạn đã chuyển một tác nhân từ nguyên mẫu sang sản xuất với Microsoft Foundry:</p>\n<ul class=\"cs-list\">\n<li>Bước chuyển sang sản xuất chủ yếu là về <strong>bộ khung vận hành</strong> xung quanh mô hình — lưu trữ, danh tính, trạng thái, xử lý lỗi, chi phí, chất lượng và sự tin cậy.</li>\n<li>Bạn đã học ba <strong>mẫu triển khai</strong> — khách hàng lưu trữ, Tác nhân Hosted và Quy trình Công việc Tác nhân — và khi nào từng loại phù hợp.</li>\n<li>Bạn đã đi qua <strong>vòng đời tác nhân</strong>, nơi đánh giá ngoại tuyến <strong>đóng vai trò cửa ngõ phát hành</strong> và khả năng quan sát trực tuyến đưa thất bại trở lại với bộ kiểm tra.</li>\n<li>Bạn đã áp dụng <strong>các chiến lược mở rộng</strong> — thiết kế không trạng thái, định tuyến mô hình, bộ nhớ đệm và giới hạn song song — và liên kết chúng với <strong>tối ưu hóa chi phí</strong>.</li>\n<li>Bạn đã kết nối các <strong>kiểm soát doanh nghiệp</strong>: RBAC, phê duyệt có người giám sát và tích hợp MCP an toàn cho sản xuất.</li>\n<li>Bạn đã xây dựng một <strong>tác nhân hỗ trợ khách hàng sẵn sàng cho sản xuất</strong> liên kết tất cả các quan ngại này với mã có thể chạy.</li>\n</ul>\n<p>Bài học tiếp theo sẽ đi theo hướng ngược lại: thay vì mở rộng các tác nhân lên đám mây, bạn sẽ đưa chúng <em>xuống</em> một máy phát triển đơn lẻ và chạy hoàn toàn cục bộ.</p>\n<h2 id=\"ai-sec-20\" class=\"cs-h2\">Tài nguyên bổ sung</h2>\n<ul class=\"cs-list\">\n<li>&lt;a href=\"https://learn.microsoft.com/azure/ai-foundry/what-is-azure-ai-foundry\" target=\"_blank\"&gt;Tài liệu Microsoft Foundry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/azure/ai-foundry/agents/overview\" target=\"_blank\"&gt;Tổng quan Dịch vụ Tác nhân Microsoft Foundry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/en-us/agent-framework/overview/?wt.mc_id=youtube_26688_organicsocial_reactor&amp;pivots=programming-language-python\" target=\"_blank\"&gt;Khung Tác nhân Microsoft&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/en-us/azure/ai-foundry/openai/concepts/model-router\" target=\"_blank\"&gt;Model Router trong Microsoft Foundry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://learn.microsoft.com/azure/search/search-what-is-azure-search\" target=\"_blank\"&gt;Azure AI Search&lt;/a&gt;</li>\n<li>&lt;a href=\"https://opentelemetry.io/\" target=\"_blank\"&gt;OpenTelemetry&lt;/a&gt;</li>\n<li>&lt;a href=\"https://github.com/marketplace/actions/ai-smoke-test\" target=\"_blank\"&gt;AI Smoke Test GitHub Action&lt;/a&gt;</li>\n<li>&lt;a href=\"https://modelcontextprotocol.io/\" target=\"_blank\"&gt;Model Context Protocol (MCP)&lt;/a&gt;</li>\n</ul>\n<h2 id=\"ai-sec-21\" class=\"cs-h2\">Bài học trước</h2>\n<p><strong>Xây dựng Tác nhân Sử dụng Máy tính (CUA)</strong></p>\n<h2 id=\"ai-sec-22\" class=\"cs-h2\">Bài học tiếp</h2>\n<p><strong>Tạo Tác nhân AI Cục bộ</strong></p>\n<p>---</p>\n<p><strong>Tuyên bố miễn trừ trách nhiệm</strong>: Tài liệu này đã được dịch bằng dịch vụ dịch thuật AI <a href=\"https://github.com/Azure/co-op-translator\" target=\"_blank\" rel=\"noopener noreferrer\">Co-op Translator</a>. Mặc dù chúng tôi cố gắng đảm bảo độ chính xác, xin lưu ý rằng bản dịch tự động có thể chứa lỗi hoặc sai sót. Tài liệu gốc bằng ngôn ngữ gốc nên được coi là nguồn tin chính thức. Đối với thông tin quan trọng, nên sử dụng dịch vụ dịch thuật chuyên nghiệp bởi con người. Chúng tôi không chịu trách nhiệm về bất kỳ hiểu lầm hoặc giải thích sai nào phát sinh từ việc sử dụng bản dịch này.</p>"}, "codeSamples": [{"name": "16-python-agent-framework.ipynb", "lang": "python", "code": "%pip install agent-framework azure-ai-projects azure-identity python-dotenv -q\n\n# ---\n\nimport logging\nlogging.getLogger(\"agent_framework.foundry\").setLevel(logging.ERROR)\n\nimport os\nimport re\nimport dotenv\nfrom typing import Annotated\n\nfrom agent_framework import tool\nfrom agent_framework.foundry import FoundryChatClient\nfrom azure.identity import AzureCliCredential\n\ndotenv.load_dotenv(dotenv.find_dotenv())\n\nendpoint = os.getenv(\"AZURE_AI_PROJECT_ENDPOINT\")\nmodel = os.getenv(\"AZURE_AI_MODEL_DEPLOYMENT_NAME\")\n\nif not endpoint or not model:\n    raise ValueError(\n        \"Missing required environment variables. \"\n        \"Please set AZURE_AI_PROJECT_ENDPOINT and AZURE_AI_MODEL_DEPLOYMENT_NAME in your .env file.\"\n    )\n\nprovider = FoundryChatClient(\n    project_endpoint=endpoint,\n    model=model,\n    credential=AzureCliCredential(),\n)\nprint(\"Foundry client ready.\")\n\n# ---\n\n# Simulated backend systems (in production these are API calls behind scoped identities).\nORDERS = {\n    \"A1001\": {\"status\": \"shipped\", \"total\": 42.00, \"eta\": \"2 days\"},\n    \"A1002\": {\"status\": \"processing\", \"total\": 128.50, \"eta\": \"5 days\"},\n    \"A1003\": {\"status\": \"delivered\", \"total\": 19.99, \"eta\": \"delivered\"},\n}\nTICKETS: list[dict] = []\nREFUND_APPROVAL_THRESHOLD = 50.0\n\n\n@tool(approval_mode=\"never_require\")\ndef get_order_status(order_id: Annotated[str, \"The customer's order ID, e.g. A1001\"]) -> str:\n    \"\"\"Look up the status of a customer order.\"\"\"\n    order = ORDERS.get(order_id.upper())\n    if not order:\n        return f\"No order found with ID {order_id}.\"\n    return (\n        f\"Order {order_id.upper()}: status={order['status']}, \"\n        f\"total=${order['total']:.2f}, eta={order['eta']}.\"\n    )\n\n\n@tool(approval_mode=\"never_require\")\ndef open_ticket(\n    subject: Annotated[str, \"Short subject line for the support ticket\"],\n    details: Annotated[str, \"Full description of the customer's issue\"],\n) -> str:\n    \"\"\"Open a support ticket for issues that need human follow-up.\"\"\"\n    ticket_id = f\"T{1000 + len(TICKETS) + 1}\"\n    TICKETS.append({\"id\": ticket_id, \"subject\": subject, \"details\": details})\n    return f\"Ticket {ticket_id} opened: {subject}\"\n\n\ndef refund_needs_approval(amount: float) -> bool:\n    \"\"\"Refunds above the threshold require a human approver.\"\"\"\n    return amount > REFUND_APPROVAL_THRESHOLD\n\n\n@tool(approval_mode=\"always_require\")\ndef issue_refund(\n    order_id: Annotated[str, \"The order to refund\"],\n    amount: Annotated[float, \"Refund amount in USD\"],\n) -> str:\n    \"\"\"Issue a refund. Execution pauses for human approval before it runs.\"\"\"\n    return f\"Refund of ${amount:.2f} issued for order {order_id.upper()}.\"\n\n\nprint(\"Tools defined.\")\n\n# ---\n\nKNOWLEDGE_BASE = {\n    \"returns\": \"Contoso accepts returns within 30 days of delivery for a full refund. Items must be unused and in original packaging.\",\n    \"shipping\": \"Standard shipping takes 3-5 business days. Express shipping (1-2 days) is available at checkout for an extra fee.\",\n    \"warranty\": \"All Contoso electronics carry a 12-month limited warranty covering manufacturing defects.\",\n    \"refund_policy\": \"Refunds are processed to the original payment method within 5 business days of approval. Refunds over $50 require a supervisor's approval.\",\n}\n\n\ndef _in_memory_search(query: str) -> str:\n    q = query.lower()\n    hits = [text for key, text in KNOWLEDGE_BASE.items() if key.replace(\"_\", \" \") in q or key in q]\n    if not hits:\n        # crude keyword fallback so the tool still returns something useful\n        hits = [text for text in KNOWLEDGE_BASE.values() if any(w in text.lower() for w in q.split())]\n    return \"\\n\".join(hits) if hits else \"No matching policy found.\"\n\n\ndef _azure_search(query: str) -> str:\n    from azure.core.credentials import AzureKeyCredential\n    from azure.search.documents import SearchClient\n\n    client = SearchClient(\n        endpoint=os.environ[\"AZURE_SEARCH_SERVICE_ENDPOINT\"],\n        index_name=os.getenv(\"AZURE_SEARCH_INDEX_NAME\", \"contoso-policies\"),\n        credential=AzureKeyCredential(os.environ[\"AZURE_SEARCH_API_KEY\"]),\n    )\n    results = client.search(search_text=query, top=3)\n    return \"\\n\".join(r.get(\"content\", \"\") for r in results) or \"No matching policy found.\"\n\n\nUSE_AZURE_SEARCH = bool(os.getenv(\"AZURE_SEARCH_SERVICE_ENDPOINT\") and os.getenv(\"AZURE_SEARCH_API_KEY\"))\n\n\n@tool(approval_mode=\"never_require\")\ndef search_policies(query: Annotated[str, \"The policy question to look up\"]) -> str:\n    \"\"\"Search Contoso support policies to answer customer questions.\"\"\"\n    if USE_AZURE_SEARCH:\n        return _azure_search(query)\n    return _in_memory_search(query)\n\n\nprint(f\"RAG ready. Using {'Azure AI Search' if USE_AZURE_SEARCH else 'in-memory search'}.\")\n\n# ---\n\nCUSTOMER_MEMORY: dict[str, dict] = {\n    \"cust-42\": {\"name\": \"Dana\", \"tier\": \"enterprise\", \"recent_order\": \"A1002\"},\n    \"cust-99\": {\"name\": \"Sam\", \"tier\": \"standard\", \"recent_order\": \"A1003\"},\n}\n\n\ndef memory_context(customer_id: str) -> str:\n    profile = CUSTOMER_MEMORY.get(customer_id)\n    if not profile:\n        return \"This is a new customer with no history.\"\n    return (\n        f\"Customer {profile['name']} ({profile['tier']} tier). \"\n        f\"Most recent order: {profile['recent_order']}.\"\n    )\n\n\nprint(memory_context(\"cust-42\"))\n\n# ---\n\nSMALL_MODEL = os.getenv(\"AZURE_AI_SMALL_MODEL\", model)   # e.g. gpt-5-nano\nLARGE_MODEL = os.getenv(\"AZURE_AI_LARGE_MODEL\", model)   # e.g. gpt-5-mini\n\nresponse_cache: dict[str, str] = {}\nroute_counters = {\"small\": 0, \"large\": 0, \"cache\": 0}\n\n\ndef normalize(query: str) -> str:\n    return re.sub(r\"\\s+\", \" \", query.lower().strip())\n\n\nCOMPLEX_SIGNALS = (\"refund\", \"cancel\", \"complaint\", \"escalate\", \"broken\", \"wrong\", \"why\")\n\n\ndef is_simple(query: str) -> bool:\n    \"\"\"Route complex or high-stakes requests to the large model; everything else to the small one.\"\"\"\n    q = query.lower()\n    if any(signal in q for signal in COMPLEX_SIGNALS):\n        return False\n    return len(q.split()) <= 20\n\n\ndef choose_model(query: str) -> str:\n    return SMALL_MODEL if is_simple(query) else LARGE_MODEL\n\n\nprint(f\"Small model: {SMALL_MODEL} | Large model: {LARGE_MODEL}\")\n\n# ---\n\n# Tracing: use the Agent Framework tracer if available, else a no-op so the notebook runs anywhere.\ntry:\n    from agent_framework.observability import get_tracer\n    tracer = get_tracer()\nexcept Exception:  # observability extras not installed\n    from contextlib import contextmanager\n\n    class _NoopSpan:\n        def set_attribute(self, *_args, **_kwargs):\n            pass\n\n    class _NoopTracer:\n        @contextmanager\n        def start_as_current_span(self, _name):\n            yield _NoopSpan()\n\n    tracer = _NoopTracer()\n\n\nSUPPORT_INSTRUCTIONS = (\n    \"You are Contoso's customer support agent. Be concise, friendly, and accurate. \"\n    \"Use search_policies for policy questions, get_order_status for orders, \"\n    \"open_ticket when a human needs to follow up, and issue_refund for refunds. \"\n    \"Never invent policy details.\"\n)\n\n# Build one agent per model tier so we can route by cost. The current agent-framework\n# selects the model on the client, so each tier gets its own FoundryChatClient.\n_TOOLS = [get_order_status, open_ticket, search_policies, issue_refund]\n_agents_by_model: dict[str, object] = {}\n\n\ndef agent_for(model_name: str):\n    if model_name not in _agents_by_model:\n        client = FoundryChatClient(\n            project_endpoint=endpoint,\n            model=model_name,\n            credential=AzureCliCredential(),\n        )\n        _agents_by_model[model_name] = client.as_agent(\n            name=\"ContosoSupportAgent\",\n            instructions=SUPPORT_INSTRUCTIONS,\n            tools=_TOOLS,\n        )\n    return _agents_by_model[model_name]\n\n\n# Default agent (used by the evaluation gate, which does not route).\nsupport_agent = agent_for(SMALL_MODEL)\n\n\nasync def handle_support_request(query: str, customer_id: str) -> str:\n    # 1. Serve from cache when we can.\n    key = normalize(query)\n    if key in response_cache:\n        route_counters[\"cache\"] += 1\n        return response_cache[key]\n\n    # 2. Route by complexity to control cost.\n    chosen_model = choose_model(query)\n    route_counters[\"small\" if chosen_model == SMALL_MODEL else \"large\"] += 1\n\n    # 3. Add per-customer memory to the prompt.\n    context = memory_context(customer_id)\n    prompt = f\"[Customer context: {context}]\\n\\n{query}\"\n\n    # 4. Run inside a trace span for observability.\n    with tracer.start_as_current_span(\"support_request\") as span:\n        span.set_attribute(\"customer.id\", customer_id)\n        span.set_attribute(\"routed.model\", chosen_model)\n        response = await agent_for(chosen_model).run(prompt)\n\n    text = response.text\n    response_cache[key] = text\n    return text\n\n\nprint(\"Support agent assembled.\")\n\n# ---\n\n# Try a few requests. The first is simple (small model), the second is a refund (large model + approval path).\nprint(await handle_support_request(\"What is your return window?\", \"cust-99\"))\nprint(\"---\")\nprint(await handle_support_request(\"Where is my order A1002?\", \"cust-42\"))\nprint(\"---\")\n# Repeat the first question -> served from cache.\nprint(await handle_support_request(\"What is your return window?\", \"cust-99\"))\nprint(\"---\")\nprint(\"Routing counters:\", route_counters)\n\n# ---\n\nTEST_CASES = [\n    {\"input\": \"How long do I have to return an item?\", \"expected\": [\"30 days\", \"refund\"]},\n    {\"input\": \"How fast is standard shipping?\", \"expected\": [\"3-5\", \"business days\"]},\n    {\"input\": \"What is the status of order A1001?\", \"expected\": [\"shipped\", \"A1001\"]},\n    {\"input\": \"Do your electronics have a warranty?\", \"expected\": [\"12-month\", \"warranty\"]},\n]\n\n\ndef score_response(actual: str, expected_keywords: list[str]) -> float:\n    actual_l = actual.lower()\n    hits = sum(1 for kw in expected_keywords if kw.lower() in actual_l)\n    return hits / len(expected_keywords)\n\n\nasync def evaluation_gate(test_cases: list[dict], threshold: float = 0.8) -> bool:\n    passed = 0\n    for case in test_cases:\n        result = await support_agent.run(case[\"input\"])\n        s = score_response(result.text, case[\"expected\"])\n        status = \"PASS\" if s >= 0.5 else \"FAIL\"\n        print(f\"[{status}] {case['input']}  (score={s:.0%})\")\n        if s >= 0.5:\n            passed += 1\n    pass_rate = passed / len(test_cases)\n    print(f\"\\nEvaluation pass rate: {pass_rate:.0%} (gate: {threshold:.0%})\")\n    return pass_rate >= threshold\n\n\ngate_passed = await evaluation_gate(TEST_CASES, threshold=0.8)\nprint(\"\\nDeploy allowed:\" , gate_passed)\n\n# ---\n\nasync def release(test_cases: list[dict]) -> None:\n    print(\"Running pre-deployment evaluation gate...\\n\")\n    if await evaluation_gate(test_cases, threshold=0.8):\n        print(\"\\n✅ Gate passed — promoting agent version to the Foundry Agent Service.\")\n    else:\n        print(\"\\n❌ Gate failed — release blocked. Fix the agent and re-run.\")\n\n\nawait release(TEST_CASES)"}]};
